/*
 * Extension Ulyss — logos (26/11/2026, demandes de Guillaume). Visibles seulement sur les postes où l'extension est installée ;
 * rien n'est modifié dans Ulyss. Images embarquées en base64 : la mise à jour automatique ne transporte que des .js et .json.
 *  1. Barre latérale dépliée : le logo d'Ulyss en haut à gauche est remplacé par le logo complet (emblème + « ULYSS »).
 *     Relevé staging : #global-sidebar > div.flex… > a.reductible > img.w-3/4.h-24.object-cover ; classes en !important.
 *  2. Barre latérale repliée : a.reductible est masqué par Ulyss → l'emblème seul est affiché au-dessus du bouton de menu.
 *  3. Chaque page : le logo complet en haut, au centre de la zone de contenu, à la hauteur du titre de la page
 *     (.text-big-title). Il ne capte aucun clic et se masque de lui-même s'il recouvrirait un bouton, un champ ou un texte.
 */
(() => {
  'use strict';
  const LOGO = 'data:image/png;base64,';
  const EMBLEME = 'data:image/png;base64,';
  const ID_EMBLEME = 'ext-ulyss-logo-embleme', ID_CENTRE = 'ext-ulyss-logo-centre';

  // --- 1 et 2 : barre latérale -------------------------------------------------------------------------------------
  function barre() {
    const sb = document.getElementById('global-sidebar');
    const img = sb && sb.querySelector('a.reductible > img');
    if (!img) return;
    if (img.getAttribute('data-ext-ulyss-logo') !== '1') {
      img.setAttribute('data-ext-ulyss-logo', '1');
      img.setAttribute('data-origine', img.getAttribute('src') || '');
      img.removeAttribute('srcset');
      img.src = LOGO; img.alt = 'Ulyss';
      // Cadre d'origine gardé en hauteur (96 px) pour ne pas décaler le menu ; le logo prend la largeur et s'affiche entier.
      img.style.setProperty('width', '100%', 'important');
      img.style.setProperty('object-fit', 'contain', 'important');
    }
    const bloc = img.parentElement.parentElement;
    let e = document.getElementById(ID_EMBLEME);
    if (!e || e.parentElement !== bloc) {
      if (e) e.remove();
      e = document.createElement('img');
      e.id = ID_EMBLEME; e.src = EMBLEME; e.alt = 'Ulyss';
      e.style.cssText = 'display:none;width:40px;height:auto;flex:none;margin:0 auto 6px';
      bloc.insertBefore(e, bloc.firstChild);
    }
    const repliee = sb.getBoundingClientRect().width < 180;
    const voulu = repliee ? 'block' : 'none';
    if (e.style.display !== voulu) {
      e.style.display = voulu;
      // Repliée : emblème au-dessus du bouton de menu (le bloc passe en colonne) ; dépliée : disposition d'Ulyss.
      const lien = img.parentElement;   // garde 96 px de haut même replié : retiré de la colonne le temps du repli
      if (repliee) lien.style.setProperty('display', 'none', 'important'); else lien.style.removeProperty('display');
      if (repliee) { bloc.style.setProperty('flex-direction', 'column', 'important'); bloc.style.setProperty('padding-left', '0', 'important'); bloc.style.setProperty('padding-right', '0', 'important'); }
      else { bloc.style.removeProperty('flex-direction'); bloc.style.removeProperty('padding-left'); bloc.style.removeProperty('padding-right'); }
    }
  }

  // --- 3 : logo au centre du haut de page ----------------------------------------------------------------------------
  // Ce qui gêne vraiment sous le logo : un bouton, un champ, une image, ou du TEXTE affiché à cet endroit. Un titre ou un
  // bloc qui occupe toute la largeur mais dont le texte est ailleurs ne gêne pas (1.8.14 se masquait à tort sur ces pages).
  const CONTROLES = 'a,button,input,select,textarea,label,img,svg,canvas,.btn,[role="button"]';
  function gene(el, x, y) {
    if (!el || el === document.documentElement || el === document.body) return false;
    if (el.closest(CONTROLES)) return true;
    const plage = document.createRange();
    for (const n of el.childNodes) {
      if (n.nodeType !== 3 || !n.textContent.trim()) continue;
      plage.selectNodeContents(n);
      for (const r of plage.getClientRects()) if (x >= r.left - 6 && x <= r.right + 6 && y >= r.top - 4 && y <= r.bottom + 4) return true;
    }
    return false;
  }
  /** Titre de la page : .text-big-title (Planning) ou h1, dans la zone de contenu, près du haut. */
  function titreDePage(gauche) {
    return [...document.querySelectorAll('.text-big-title, h1, #title')].find((e) => {
      const r = e.getBoundingClientRect();
      return r.height > 0 && r.width > 0 && r.right > gauche && !e.closest('#global-sidebar');
    }) || null;
  }
  let defile = 0;   // défilement de la page ou d'une zone interne, quand aucun titre ne permet de le suivre
  function centre() {
    let c = document.getElementById(ID_CENTRE);
    const sb = document.getElementById('global-sidebar');
    if (!sb) { if (c) c.style.visibility = 'hidden'; return; }
    if (!c) {
      c = document.createElement('img');
      c.id = ID_CENTRE; c.src = LOGO; c.alt = '';
      c.setAttribute('aria-hidden', 'true');
      c.style.cssText = 'position:fixed;height:51px;width:auto;z-index:5;pointer-events:none;user-select:none;visibility:hidden;transform:translate(-50%,-50%)';
      document.body.appendChild(c);
    }
    const gauche = sb.getBoundingClientRect().right;
    const titre = titreDePage(gauche), t = titre ? titre.getBoundingClientRect() : null;
    // Hauteur : celle du titre s'il est près du haut ; sinon 40 px du haut (hauteur habituelle des titres d'Ulyss), page non défilée.
    const suivi = t && t.top < 160;
    const x = gauche + (window.innerWidth - gauche) / 2, y = suivi ? t.top + Math.min(t.height, 48) / 2 : 40;
    c.style.left = Math.round(x) + 'px'; c.style.top = Math.round(y) + 'px';
    let visible = suivi ? (y > 12 && y < window.innerHeight - 12) : defile < 8 && !(t && t.top < 0);
    if (visible) {
      const l = (c.naturalWidth && c.naturalHeight ? 51 * c.naturalWidth / c.naturalHeight : 300) + 24;
      for (const f of [-0.5, -0.25, 0, 0.25, 0.5]) {
        const px = x + f * l, dessous = document.elementsFromPoint(px, y).find((el) => el !== c);
        if (gene(dessous, px, y)) { visible = false; break; }
      }
    }
    c.style.visibility = visible ? 'visible' : 'hidden';
  }

  let prevu = false;
  function poser() {
    if (window.__extUlyssActif && !window.__extUlyssActif('logos')) return;
    if (prevu) return;
    prevu = true;
    requestAnimationFrame(() => { prevu = false; try { barre(); centre(); } catch (e) { /* jamais bloquant */ } });
  }
  document.addEventListener('turbo:load', poser);
  window.addEventListener('resize', poser);
  document.addEventListener('scroll', (e) => {               // y compris le défilement d'une zone interne
    const z = e.target === document ? document.scrollingElement : e.target;
    if (z && !(z.closest && z.closest('#global-sidebar')) && z.clientHeight > window.innerHeight * 0.5) defile = z.scrollTop || 0;
    poser();
  }, true);
  document.addEventListener('turbo:load', () => { defile = 0; });
  document.addEventListener('transitionend', poser, true);   // fin du repli / dépli de la barre
  new MutationObserver(poser).observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
  poser();
})();
